#!/usr/bin/env python3
"""Writes the hedra command files of the dragon tower's simple models (from art/assets.md, no sheet):
tower, ladder, ground, hills, tree, cloud, knight, fireball, poof. Up Z, facing -Y, origin on the
ground under the centre (the knight's at its feet, the fireball's and poof's at their centre).
Run from this folder: python3 make_env.py; then `hedra model --text <m>.rmdl run <m>.txt` (build.sh)."""
import math

COL = {  # Blessing, sRGB 0..1
    "P": "0.455 0.337 0.608", "T": "0.847 0.749 0.847", "K": "1.0 0.702 0.796",
    "M": "0.588 0.984 0.780", "Y": "0.969 1.0 0.682"}

def mats(L, *pairs):
    for name, col in pairs:
        L.append(f"material new {name} --base-color {COL[col]} --no-slot")

def box(L, name, loc, size, mat=None, rot=None):
    L.append(f"add mesh cube --name {name} --size 1 --location {loc[0]:.3f} {loc[1]:.3f} {loc[2]:.3f}")
    L.append(f"scale {size[0]:.3f} {size[1]:.3f} {size[2]:.3f}")
    L.append("apply --scale")
    if rot:
        L.append(f"set rotation {rot[0]:.2f} {rot[1]:.2f} {rot[2]:.2f}")
    if mat:
        L.append(f"material assign {mat}")

def write(name, L, glb=None):
    L += ["select all", "shade flat", f"export {glb or name}.glb"]
    open(f"{name}.txt", "w").write("\n".join(L) + "\n")

# --- tower: an octagonal keep, 2.5 m across, 5.4 m to the walk, a corbelled parapet with 8 merlons,
# a purple plinth course, arrow slits standing 0.1 m proud (dark purple), a floor on top for the dragon
L = ["# The dragon's tower (generated by make_env.py): 4.4 m keep, the walk at 4.7 m. Octagon, faces towards the 8 compass points.", "new"]
mats(L, ("Stone", "T"), ("Dark", "P"))
L.append("add mesh cylinder --name Keep --vertices 8 --radius 1.35 --depth 4.4 --location 0 0 2.2 --rotation 0 0 22.5")
L.append("material assign Stone")
L.append("add mesh cylinder --name Plinth --vertices 8 --radius 1.5 --depth 0.5 --location 0 0 0.25 --rotation 0 0 22.5")
L.append("material assign Dark")
L.append("add mesh cylinder --name Corbel --vertices 8 --radius 1.55 --depth 0.3 --location 0 0 4.35 --rotation 0 0 22.5")
L.append("material assign Dark")
L.append("add mesh cylinder --name Walk --vertices 8 --radius 1.6 --depth 0.2 --location 0 0 4.6 --rotation 0 0 22.5")
L.append("material assign Stone")
ap = 1.6 * math.cos(math.radians(22.5)) - 0.14
for k in range(8):
    a = math.radians(45 * k)
    x, y = ap * math.sin(a), -ap * math.cos(a)
    box(L, f"Merlon{k}", (x, y, 4.95), (0.62, 0.26, 0.5), "Stone", (0, 0, 45 * k))
# arrow slits on the faces between the ladders (ladders at 0 and +-50 deg: slits at +-25 and +-90)
ap2 = 1.35 * math.cos(math.radians(22.5)) + 0.05
for k, (deg, z) in enumerate(((-90, 2.6), (90, 3.0), (-135, 2.0), (135, 2.4), (180, 2.6), (-25, 3.5), (25, 1.7))):
    a = math.radians(deg)
    box(L, f"Slit{k}", (ap2 * math.sin(a), -ap2 * math.cos(a), z), (0.2, 0.2, 0.55), "Dark", (0, 0, deg))
# a door at the back-left, so the front stays clear for the ladders
a = math.radians(-155)
box(L, "Door", (1.3 * math.sin(a), -1.3 * math.cos(a), 0.9), (0.7, 0.2, 1.3), "Dark", (0, 0, -155))
write("tower", L)

# --- ladder: two rails and 10 rungs, 4.4 m tall, 0.6 m wide; stands upright against the wall
L = ["# A wooden ladder (generated by make_env.py): rails 0.1 m, rungs every 0.45 m.", "new"]
mats(L, ("Wood", "Y"))
for s in (-1, 1):
    box(L, f"Rail{'LR'[s > 0]}", (0.27 * s, 0, 2.2), (0.1, 0.1, 4.4), "Wood")
for k in range(10):
    box(L, f"Rung{k}", (0, 0, 0.35 + 0.42 * k), (0.5, 0.08, 0.08), "Wood")
write("ladder", L)

# --- ground: the meadow, a top-only plane 18 x 16 m (glTF z -9..7), and a low knoll under the tower
# (its hidden bottom deleted); a flagstone path to the front edge
L = ["# The meadow round the tower (generated by make_env.py).", "new"]
mats(L, ("Grass", "M"), ("Path", "T"))
L.append("add mesh plane --name Plain --size 1 --location 0 1 0")
L.append("scale 18 16 1")
L.append("apply --scale")
L.append("material assign Grass")
L.append("add mesh cone --name Knoll --vertices 10 --radius1 3.4 --radius2 2.3 --depth 0.36 --location 0 0 0.0")
L.append("material assign Grass")
L += ["mode edit", "select face where \"normal.z < -0.5\"", "delete face", "mode object"]
for k in range(6):
    box(L, f"Flag{k}", (0.25 * (-1) ** k, -3.2 - 0.75 * k, 0.03), (0.6, 0.45, 0.1), "Path", (0, 0, 10 * (-1) ** k))
write("ground", L)

# --- hills: three rolling, faceted hills on the horizon (for far away: fog thins them)
L = ["# Distant hills (generated by make_env.py).", "new"]
mats(L, ("Hill", "M"))
for k, (x, y, r, h) in enumerate(((-9, 0, 5.5, 1.1), (1.5, 2.5, 6.5, 1.5), (11, 0.5, 5.0, 0.9), (-17, 2, 5, 0.8))):
    L.append(f"add mesh uv-sphere --name Hill{k} --segments 10 --rings 6 --radius 1 --location {x} {y} 0")
    L.append(f"scale {r} {r * 0.6} {h}")
    L.append("apply --scale")
    L.append("material assign Hill")
    L += ["mode edit", "select face where \"pos.z < 0.05\"", "delete face", "mode object"]
write("hills", L)

# --- tree: a blossom tree, a purple trunk and three pink puffs
L = ["# A blossom tree (generated by make_env.py), 2.6 m tall.", "new"]
mats(L, ("Bark", "P"), ("Bloom", "K"))
L.append("add mesh cylinder --name Trunk --vertices 6 --radius 0.16 --depth 1.4 --location 0 0 0.7")
L.append("material assign Bark")
for k, (x, y, z, r) in enumerate(((0, 0, 1.75, 0.75), (-0.45, 0.1, 1.45, 0.5), (0.45, -0.1, 1.5, 0.52))):
    L.append(f"add mesh ico-sphere --name Puff{k} --subdivisions 1 --radius {r} --location {x} {y} {z}")
    L.append("material assign Bloom")
write("tree", L)

# --- cloud: a flat-bottomed cluster of puffs, 3.6 m wide (unlit in the bake)
L = ["# A cloud (generated by make_env.py), 3.6 x 1.4 x 1.4 m.", "new"]
mats(L, ("Cloud", "Y"))
for k, (x, z, r) in enumerate(((-1.1, 0.45, 0.6), (-0.2, 0.75, 0.85), (0.8, 0.55, 0.7), (1.45, 0.35, 0.45))):
    L.append(f"add mesh ico-sphere --name Puff{k} --subdivisions 1 --radius {r} --location {x} 0 {z}")
    L.append("scale 1 0.7 1")
    L.append("apply --scale")
    L.append("material assign Cloud")
write("cloud", L)

# --- knight: 0.85 m, a purple steel helmet and greaves, a mint tunic, a pink plume, a round pink
# shield with a yellow boss slung on the BACK (+Y: the climbing knight shows it), a short spear
L = ["# A knight (generated by make_env.py): 0.85 m tall, origin at the feet, facing -Y.", "new"]
mats(L, ("Steel", "P"), ("Tunic", "M"), ("Shield", "K"), ("Boss", "Y"), ("Plume", "K"))
for s in (-1, 1):
    box(L, f"Leg{'LR'[s > 0]}", (0.09 * s, 0, 0.14), (0.12, 0.14, 0.28), "Steel")
box(L, "Body", (0, 0, 0.42), (0.36, 0.26, 0.34), "Tunic")
for s in (-1, 1):
    box(L, f"Arm{'LR'[s > 0]}", (0.23 * s, -0.02, 0.44), (0.1, 0.12, 0.28), "Steel")
L.append("add mesh cylinder --name Helm --vertices 6 --radius 0.15 --depth 0.24 --location 0 0 0.72")
L.append("material assign Steel")
L.append("add mesh cone --name Plume --vertices 4 --radius1 0.08 --radius2 0.0 --depth 0.26 --location 0 0.05 0.94 --rotation -30 0 0")
L.append("material assign Plume")
L.append("add mesh cylinder --name Shield --vertices 8 --radius 0.21 --depth 0.06 --location 0 0.17 0.45 --rotation 90 0 0")
L.append("material assign Shield")
L.append("add mesh cylinder --name BossK --vertices 4 --radius 0.07 --depth 0.06 --location 0 0.21 0.45 --rotation 90 0 0")
L.append("material assign Boss")
write("knight", L)

# --- fireball: a yellow core with five pink flame licks (unlit in the bake), 0.7 m across
L = ["# A fireball (generated by make_env.py): origin at its centre.", "new"]
mats(L, ("Core", "Y"), ("Flame", "K"))
L.append("add mesh ico-sphere --name Core --subdivisions 1 --radius 0.24 --location 0 0 0")
L.append("material assign Core")
for k, (rx, rz) in enumerate(((0, 0), (70, 30), (70, 150), (70, 270), (130, 90))):
    sx, cx = math.sin(math.radians(rx)), math.cos(math.radians(rx))
    p = [0.3 * sx * math.sin(math.radians(rz)), -0.3 * sx * math.cos(math.radians(rz)), 0.3 * cx]
    L.append(f"add mesh cone --name Lick{k} --vertices 4 --radius1 0.15 --radius2 0 --depth 0.34 "
             f"--location {p[0]:.3f} {p[1]:.3f} {p[2]:.3f} --rotation {rx} 0 {rz}")
    L.append("material assign Flame")
write("fireball", L)

# --- poof: a puff of smoke for hits and the dragon's overheated nostrils
L = ["# A puff (generated by make_env.py): three icospheres, origin at the centre.", "new"]
mats(L, ("Puff", "Y"))
for k, (x, z, r) in enumerate(((0, 0.05, 0.3), (-0.22, -0.08, 0.2), (0.22, -0.06, 0.22))):
    L.append(f"add mesh ico-sphere --name Puff{k} --subdivisions 1 --radius {r} --location {x} 0 {z}")
    L.append("material assign Puff")
write("poof", L)
print("wrote tower ladder ground hills tree cloud knight fireball poof .txt")
